from decimal import Decimal
from typing import Any


def _value(record: dict, field: str) -> Any:
    return record.get(field, "")


def _old_value(old: dict | None, field: str) -> Any:
    if old is None:
        return ""
    return old.get(field, "")


def _length(value: Any) -> int:
    if value is None or value == "":
        return 0
    return len(str(value))


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    if event in ("INSERT", "UPDATE"):
        if not (_length(_value(record, "ACCT_NM")) >= 2):
            errors.append({
                "code": "E1001",
                "message": "Account name too short",
                "severity": "BLOCK",
            })

    if event in ("INSERT", "UPDATE"):
        account_type = _value(record, "ACCT_TYP")
        if not (
            account_type == "C"
            or account_type == "P"
            or account_type == "R"
            or account_type == "X"
        ):
            errors.append({
                "code": "E1002",
                "message": "Invalid account type",
                "severity": "BLOCK",
            })

    if event in ("INSERT", "UPDATE"):
        if not (_number(_value(record, "ANN_REV")) >= Decimal(0)):
            errors.append({
                "code": "E1003",
                "message": "Annual revenue negative",
                "severity": "BLOCK",
            })

    if event == "UPDATE":
        release_with_no_limit = (
            _old_value(old, "CRED_HOLD") == "Y"
            and _value(record, "CRED_HOLD") == "N"
            and _number(_value(record, "CRED_LIMIT")) <= Decimal(0)
        )
        if release_with_no_limit:
            errors.append({
                "code": "E1004",
                "message": "Cannot release credit hold with zero credit limit",
                "severity": "BLOCK",
            })

    if event in ("INSERT", "UPDATE"):
        if not (_length(_value(record, "REGION_CD")) == 3):
            errors.append({
                "code": "E1005",
                "message": "Region code must be 3 chars",
                "severity": "WARN",
            })

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
